class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        for i in range(1, n):
            best = 0
            for j in range(i):
                best = max(best, dp[j] + (i - j) * nums[j])
            dp[i] = best
        return dp[-1]

