class Solution {
public:
    long long maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<long long> dp(n, 0);
        for (int i = 1; i < n; i++) {
            long long best = 0;
            for (int j = 0; j < i; j++)
                best = max(best, dp[j] + (long long)(i - j) * nums[j]);
            dp[i] = best;
        }
        return dp[n - 1];
    }
};

